const A=require('node:assert/strict'),Q=require('./aquatic');const tests=[];let results={};function test(n,f){f();tests.push(n)}function run(s,n){for(let i=0;i<n;i++){Q.tick(s);for(const [k,v] of Object.entries(s.last))A.ok(Math.abs(v)<1e-6,k+': '+v);for(const r of s.aqua){A.ok(r.ground>=0&&r.pond>=0);for(const k of Q.names)for(const q of Object.values(r[k]))A.ok(q>=-1e-12);for(const k of ['c','n','p'])A.ok(Math.abs(r.eggs[k]-r.cohorts.reduce((v,e)=>v+e[k],0))<1e-8)}}return s}
test('sete refúgios finitos',()=>{let s=Q.create();A.equal(s.aqua.filter(r=>r.deep).length,7);s.weather='drought';run(s,120);A.equal(Q.metrics(s).refuges,7);A.ok(Q.metrics(s).fish>.1);A.ok(s.aquaEvents.baseflow>0)});
test('seca prolongada esgota as reservas sem reposição artificial',()=>{let s=Q.create();s.weather='drought';run(s,360);results.drought90=Q.metrics(s);A.equal(results.drought90.refuges,0);A.ok(results.drought90.ground<Q.metrics(Q.create()).ground)});
test('ovos têm período mínimo de incubação',()=>{let s=Q.create();run(s,56);A.ok(s.aquaEvents.spawnC>0);A.equal(s.aquaEvents.hatchC,0);run(s,8);A.ok(s.aquaEvents.hatchC>0);A.ok(s.aquaEvents.matureC>0)});
test('insetos reais transferem matéria para água',()=>{let s=Q.create();s.weather='storm';run(s,120);A.ok(s.aquaEvents.insectCount>0);A.ok(s.aquaEvents.insectC>0)});
test('migração depende de trechos conectados',()=>{let s=Q.create();s.weather='drought';run(s,120);A.ok(s.aquaEvents.migrationC>0)});
test('ovos inviáveis retornam aos detritos',()=>{let s=Q.create();for(let i=0;i<4;i++)Q.tick(s);let r=s.aqua.find(r=>r.cohorts.length);A.ok(r);let old=r.eggs.c;r.o=0;run(s,1);A.ok(r.eggs.c<old)});
test('sem passagem em trecho seco',()=>{let s=Q.create();s.weather='drought';for(let r of s.aqua){r.ground=0;r.pond=0}for(let c of s.cells){c.surface=0;c.water=0}run(s,4);A.equal(s.aquaEvents.migrationC,0)});
console.log(JSON.stringify({passed:tests.length,tests,results},null,2));
